    "id": "expansion-a-006",
    "title": "航站楼里的旧照片",
    "englishTitle": "The Airport Photograph",
    "category": "修仙志",
    "tag": "归墟修行录",
    "color": "#dce5d9",
    "symbol": "☾",
    "mood": "疑虑 → 危机 → 释然",
    "cn": [
      "富裕商人向非洲农业援助机构捐赠，代理人却想把资金改用于私人航班。林遥在机场相册里看到非洲农民的合影，决定反对这项议程。",
      "代理人因揭穿而变得咄咄逼人。他的攻击使林遥更加痛苦，空调失灵又加剧了众人的烦躁；警报响起，通道里的人纷纷逃跑。",
      "林遥先安抚旅客，再说明粮食项目的目标。商人看到总账后同意恢复援助。私人飞机随后取消，村民总算能负担种子。"
    ],
    "en": [
      "An [[affluent]] donor linked his [[affluence]] to [[agriculture]] in [[africa|Africa]]. An [[african|African]] photograph in an [[airport]] [[album]] moved Lin to act [[against]] an [[agency]] [[agent]] whose [[agenda]] favored a private [[airline]].",
      "The [[aggressive]] agent’s [[aggression]] caused [[agitation]] and [[agony]]. Broken [[air-conditioning]] could [[aggravate]] it; an [[alarm]] emptied the [[aisle]] beside the [[aircraft]]. [[alas|Alas]], the [[airplane]] carried gifts rather than grain.",
      "Lin’s [[aim]] was to restore [[aid]]. The [[aggregate]] budget convinced the donor to become [[agreeable]]. [[afterward|Afterward]], villagers could [[afford]] seeds again."
    ],
