      "他却发现，与星图联系在一起的资产评估根本不可靠。大家想当然地以为航线价值巨大，他坚定地指出图上的海岸已经改变。",
      "一位从大西洋归来的运动员证实了他的话。这个懂天文学和天体物理的新人让大家吃惊；他的任务从估价变成了保护航行者。"
