    "mood": "疑虑 → 危机 → 释然",
    "cn": [
      "一个新手乞丐拾到一颗漂亮珠子，相信它能让妖兽听话。他把珠子挂在胡须上，坐在横梁下，怀里装满豆子。",
      "蜜蜂与甲虫使他误以为妖兽正在现身；他提前请求林遥代表自己祈福。林遥告诉他，有感知的生灵不属于谁，也不能被随意驱使。",
      "林遥教他观察行为而不是妄求控制。少年改变举止，把珠子放回池边；从那以后，他的修行真正开始。"
    ],
    "en": [
      "A [[beginner]] [[beggar]] found a [[bead]] of rare [[beauty]]. His [[belief]] was that it controlled a [[beast]]. He hung it in his [[beard]], sat beneath a [[beam]], and filled his [[belly]] with [[bean|beans]].",
      "A [[bee]] and a [[beetle]] disturbed his [[bearing]]. [[beforehand|Beforehand]], he would [[beg]] Lin to pray on his [[behalf]]. Lin said no living [[being]] could simply [[belong]] to him.",
      "Learning to [[behave]] kindly changed his [[behavior]]. He returned the bead and fed the insects. That was the true [[beginning]] of his practice."
    ],
