      "梅盖上毯子，按住伤口。空白账页看似使前景黯淡，但她眨眼时看清了血衣旁的一朵花；毒物其实来自花汁。",
      "金发人没有被定罪。铁匠让花园重新开花，病人获救；他不再把可怕事故归咎于无法看见的人。"
