    "mood": "疑虑 → 危机 → 释然",
    "cn": [
      "化学家在下棋时吃樱桃、奶酪和栗子，支票放在箱子里。梅发现棋子的颜色会变，追赶一名骗子时却险些落入深渊。",
      "骗子扬起脸颊，得意地闲聊。梅检查棋子上的木炭粉，发现了那位化学家珍爱的药方；他把药物成分藏在残局里，是为了保护家人。",
      "她没有让骗子毁掉棋盘。化学变化的证据揭破谎言，众人欢呼；化学家终于能愉快地回到餐桌，细嚼自己的点心。"
    ],
    "en": [
      "A [[chemist]] played [[chess]] with [[cherry|cherries]], [[cheese]], and a [[chestnut]] snack beside a [[chest]] holding a [[cheque]]. Mei’s [[chase]] of a [[cheat]] nearly ended at a [[chasm]].",
      "The thief puffed his [[cheek]] and kept up idle [[chatter]]. [[charcoal]] marks on the pieces hid a [[chemical]] recipe the chemist would [[cherish]]. His knowledge of [[chemistry]] had made the board a safe archive.",
      "Mei saved it and proved the theft. Neighbours began to [[cheer]], and the [[cheerful]] chemist sat down to [[chew]] his snack in peace."
    ],
