    "id": "expansion-a-037",
    "title": "烟囱后的童年信",
    "englishTitle": "The Childhood Letter behind the Chimney",
    "category": "修仙志",
    "tag": "归墟修行录",
    "color": "#dce5d9",
    "symbol": "☾",
    "mood": "疑虑 → 危机 → 释然",
    "cn": [
      "村长给林遥看童年的信。信藏在烟囱后，纸上沾着巧克力碎屑；村长说小时候他常偷吃栗子，险些噎住。",
      "村民要在火灾后选择赔偿对象，村长被指责还像孩子一样偏心。他承认自己选的鸡肉和厚重食物并不适合大家，而人们真正担心的是安全。",
      "林遥看见村长下巴上的旧疤，理解那次噎食为何使他害怕。村长砍去遮挡烟道的木块，把优先权给了最需要帮助的家庭。"
    ],
    "en": [
      "The village [[chief]] showed Lin a [[childhood]] letter behind a [[chimney]], stained with a [[chip]] of [[chocolate]]. Eating [[chicken]] in the [[chill]], he admitted that he had once begun to [[choke]] on food.",
      "Villagers had a [[choice]] after a fire: whom should they [[choose]] for aid? They called his preference [[childish]]. Rich meals and worries about [[cholesterol]] had distracted him from their need for safety.",
      "An old mark on his [[chin]] explained his fear. He would [[chop]] away the wood blocking the flue and put vulnerable households first."
    ],
