    "id": "expansion-a-038",
    "title": "圣诞夜的环形电路",
    "englishTitle": "The Circular Circuit on Christmas Eve",
    "category": "修仙志",
    "tag": "归墟修行录",
    "color": "#dce5d9",
    "symbol": "☾",
    "mood": "疑虑 → 危机 → 释然",
    "cn": [
      "圣诞夜，教堂唱诗班唱着关于基督的赞歌。一个长期病患突然倒下，林遥在编年史里看到同样的记录。",
      "有人说病人只是吸了雪茄或香烟，林遥却检查到环形电路影响了屋内空气流通。循环装置上的香烟标记写着一个旧拼法，说明它一直未被更换。",
      "林遥切断电路，让空气重新流动。圆圈的周长只是设计数据，真正重要的是病人有无新鲜空气；基督徒医生把病人救了回来。"
    ],
    "en": [
      "At [[christmas|Christmas]], a [[church]] [[chorus]] sang of [[christ|Christ]]. A [[chronic]] patient collapsed; Lin found the same event in a [[chronicle]]. A broken [[chord]] startled the singers.",
      "A [[chunk]] of tobacco suggested a [[cigar]] or [[cigarette]]. Yet an old label said [[cigaret]], revealing an obsolete [[circular]] [[circuit]]. Bad [[circulation]] prevented air from moving round the room.",
      "Lin opened the [[circle]] and let fresh air [[circulate]]. The [[circumference]] mattered less than the patient’s breath. A [[christian|Christian]] doctor saved him."
    ],
