      "会议一度成为对峙，众人因为要求一致而陷入混乱。梅让水汽在冰冷的混凝土表面凝结，说明低温表面怎样产生了滴水。",
      "管理员承认没有记录建筑状况，但不必因破坏被谴责。梅限制争吵，使双方一致接受修理方案；决定性的证据让会议得以继续。"
