    "mood": "疑虑 → 危机 → 释然",
    "cn": [
      "表亲送来一件昂贵的棉布戏服，声称它画着宇宙的真实形状。梅在温暖的小屋里数星点，却因灰尘咳个不停。",
      "县议会请她和同级顾问一起研究。她们在沙发上对照图案，发现所谓宇宙地图只是店铺的优惠券设计。",
      "两位表亲诚恳地接受建议，退回戏服。梅的勇气使她没有迎合那对夫妇的幻想；柜台后的售货员也因此修正了广告。"
    ],
    "en": [
      "A [[cousin]] brought a [[costly]] [[cotton]] [[costume]] bearing the [[cosmos]]. In a [[cottage]], Mei tried to [[count]] its [[cosmic]] dots but began to [[cough]]. A [[couple]] insisted it was real.",
      "The [[county]] [[council]] asked her [[counterpart]] for [[counsel]]. On a [[couch]], they found the design was a shop [[coupon]]. Their [[counseling]] could [[counteract]] the sales claim.",
      "With [[courage]], the [[courageous]] cousins returned it at the [[counter]]. Their decision made the shop correct its advertisement."
    ],
