      "Mei would [[deploy]] investigators. [[dense|Dense]] [[dental]] scans and mineral [[density]] proved treatment dates; a surface [[deposition]] showed what filled a tooth at its [[depth]]. The family must not [[depend]] on rumour.",
      "She stopped an order that could [[deprive]] them of freedom and [[depress]] a [[dependent]] child into [[depression]]. They could [[depart]] safely, with cleared names."
