      "信使的目的地是废墟中的病人。别人鄙视这份礼物，说绝望的人更需要药；林遥却认为，病人也值得拥有一点心愿。",
      "他指定一条更理想的路线，派送药品和甜点。尽管险阻重重，祖先路线的由来终于获得解释：它是为了让人安全抵达，而不是证明血统。"
