    "id": "expansion-a-067",
    "title": "命运探测器的误差",
    "englishTitle": "The Error in the Destiny Detector",
    "category": "悬疑案",
    "tag": "雾城异闻",
    "color": "#dfdad0",
    "symbol": "◈",
    "mood": "疑虑 → 危机 → 释然",
    "cn": [
      "侦探受邀检验一台命运探测器，发明者说它注定能判断谁会毁灭城市。细节里，一个小偏差却使梅停下来。",
      "发明者想扣留被点名的人。梅拆下探测装置，发现模型还处于发展阶段；它偏离真实数据，根本无法检测危险。",
      "梅决心阻止这项破坏性预言。她确定真正的问题是恐惧，拒绝让所谓命运决定人的自由；机器停止了，城市也没有被摧毁。"
    ],
    "en": [
      "A [[detective]] tested a [[detector]] said to [[determine]] [[destiny]]. Its maker would [[destine]] one person for blame: someone was [[destined]] to [[destroy]] the city. A small [[detail]] of [[deviation]] troubled Mei.",
      "He wanted to [[detain]] that person. Mei would [[detach]] the [[device]] and inspect its [[developmental]] model. It began to [[deviate]] from real evidence; its [[detection]] could not [[detect]] danger.",
      "With [[determination]], she stopped the [[destructive]] prediction. Fear, not fate, threatened [[destruction]]. The machine fell silent, and nobody lost freedom."
    ],
