    "id": "expansion-a-068",
    "title": "方言里的钻石日记",
    "englishTitle": "The Diamond Diary in the Dialect",
    "category": "修仙志",
    "tag": "归墟修行录",
    "color": "#dce5d9",
    "symbol": "☾",
    "mood": "疑虑 → 危机 → 释然",
    "cn": [
      "林遥在露水中找到一本日记，画着钻石的直径图。村民说，一个魔鬼会吃掉读者，他却决定听听真实的方言对话。",
      "医生用诊断图检验村里的疾病，柴油机器的刻度盘暴露了泄漏。林遥设计了修复办法，知道真正的危险不是诅咒。",
      "老人向他口授经过，年轻人记录听写；统治村庄的独裁者终于无法篡改故事。林遥把奉献留给病人，而不是留给恐惧。"
    ],
