    "title": "码头边的海豚纪录片",
    "englishTitle": "The Dolphin Documentary by the Dock",
    "category": "修仙志",
    "tag": "归墟修行录",
    "color": "#dce5d9",
    "symbol": "☾",
    "mood": "疑虑 → 危机 → 释然",
    "cn": [
      "博士生在码头拍纪录片，镜头里的海豚却被垃圾困住。她与丈夫离婚后，原本想借这次旅行避开痛苦。",
      "暴雨改变水道，使河沟的水流转向。林遥潜水帮助分配救援物资，试着分流汹涌的水；那些被叫作神迹的事，其实需要多样的技能。",
      "不同意见的志愿者把工作分开，海豚重获自由。女孩虽仍头晕，却不再受狭窄教条支配；她把镜头交给整个地区的救援者。"
    ],
    "en": [
      "A [[doctoral]] student made a [[documentary]] at a [[dock]], where a [[dolphin]] was trapped. After a [[divorce]], she hoped to [[dodge]] [[distress]]. Rain began to [[disturb]] the [[district]].",
      "Water left a [[ditch]] and made currents [[diverge]]. Lin would [[dive]] to [[distribute]] supplies, organizing [[distribution]] and a [[diversion]] to [[divert]] floods. No [[divine]] gift replaced [[diverse]] skills.",
      "They would [[divide]] duties; their [[division]] helped [[diversify]] the rescue. Skill [[diversity]] freed the dolphin. Though [[dizzy]], the student rejected rigid [[doctrine]] and filmed everyone’s help."
    ],
