      "宿舍里一名学生给病人一剂药，唤醒沉睡的生机。楼下十二只鸽子聚在白鸽标记旁，商人却怀疑药能使人向下沉沦。",
      "林遥质疑他没有根据的恐惧。捐赠继续，家用物资送到住户；灾难并不注定发生，而疑虑不该让人放弃善行。"
