    "id": "expansion-a-076",
    "title": "排水龙的图纸",
    "englishTitle": "The Drawing of the Drainage Dragon",
    "category": "修仙志",
    "tag": "归墟修行录",
    "color": "#dce5d9",
    "symbol": "☾",
    "mood": "疑虑 → 危机 → 释然",
    "cn": [
      "旱灾中，林遥从抽屉拿出龙形排水装置的图纸。旧草稿的缺点是会让水流漂走，但人们已经害怕得不敢再尝试。",
      "他听着练习鼓声，拖来钻机，在冷风中钻孔。药剂与酒后误事都曾造成可怕后果，林遥于是要求施工时保持清醒。",
      "水滴终于汇成水流，骤然的变化仿佛一出戏。林遥没有沉迷梦中的神龙，而是修复真实排水系统；最后一滴水落下，村子有救了。"
    ],
    "en": [
      "In a [[drought]], Lin found a [[dragon]] [[drawing]] in a [[drawer]]. The [[draft]] had a [[drawback]]: its [[drainage]] let water [[drift]]. Villagers felt [[dread]] of another [[dreadful]] failure.",
      "To a practice [[drum]], he would [[drag]] a [[drill]] into a cold [[draught]]. A [[drug]] and a [[drunk]] worker had caused the last accident. He required sober hands before any [[drastic]] repair.",
      "A [[drip]] became a flow through the [[drain]]. The [[dramatic]] change felt like [[drama]], but he trusted work over a [[dream]]. Each [[drop]] now reached the fields."
    ],
