      "这套双重动力装置还很耐用，可染液倾倒入河后，鸭子正在死亡。工人呆呆地看着水面，怀疑公爵虚假的承诺。",
      "黄昏时，他履行责任，关闭机器。梅帮助检测动力系统，使生产重新有活力；住户获得干净的河水，染坊不再以繁荣掩盖污染。"
