    "color": "#dce5d9",
    "symbol": "☾",
    "mood": "疑虑 → 危机 → 释然",
    "cn": [
      "一个古怪的陶工在复活节卖鹰纹陶罐，热切地想赚收入。地震使他所有罐子倾倒，山谷里回荡着碎裂的回声。",
      "林遥向东赶来，看到东方山缘的可食植物被破坏。当地经济原本依靠生态系统，日食期间的游客却忽视了这一点。",
      "两人认真学习经济学与生态学，以节省又实际的办法修复村落。陶工不再轻易扩建，收入慢慢恢复；山谷的压力也得到缓解。"
    ],
    "en": [
      "An [[eccentric]] potter sold [[eagle]] [[earthenware]] at [[easter|Easter]], [[eager]] to [[earn]] [[earnings]]. An [[earthquake]] broke the pots, and an [[echo]] filled the valley.",
      "Lin travelled [[eastward]] to the [[eastern]] [[edge]]. [[edible|Edible]] plants had suffered. The [[economy]] depended on the [[ecosystem]], but visitors during an [[eclipse]] ignored its [[ecology]].",
      "With [[earnest]] study of [[economics]], they made an [[economical]] repair [[economically]]. [[economic|Economic]] recovery did not come [[easily]], yet careful work could [[ease]] the village’s loss."
    ],
