      "梅检查刺绣展示柜，发现线路嵌入布料，正散发浓烟。那不是任何情绪的象征，而是真实的电气故障。",
      "大家准备离开时，工作人员及时开启通风。家人拥抱在一起，不必再去别处办理；那位职员也明白，说话的雄辩不如行动体现责任。"
