      "林遥遭遇看守，劝他鼓起勇气。这里的围地曾让人着迷，如今无穷扩张的欲望会危及生命；授权不能代替责任。",
      "员工获得权力去关闭猎场，两个部门共同努力。林遥说，赐给人耐力的不是皇权，而是守住承诺；故事的结尾终于留给活着的森林。"
