    "cn": [
      "一位英国工程师来教村民修理巨型引擎。林遥很有精力，想报名参加，但村民把外来的师傅当成敌人。",
      "他发出询问，说明这项工作需要怎样的投入。问询之后，大家理解安全保证包含培训，而不是只靠热情；知识能使他们的生活更丰富。",
      "村民一起加大管道，改进性能。理解消除了敌意，能量重新流动；他们投入工程，才发现启蒙来自动手与认真追问。"
    ],
    "en": [
      "An [[englishman|Englishman]] [[engineer]] taught [[engineering]] for an [[enormous]] [[engine]]. [[energetic|Energetic]] Lin wanted to [[enroll]], but villagers called the teacher an [[enemy]]. His [[energy]] could not fix suspicion.",
      "Lin would [[enquire]] what an [[engagement]] would [[entail]]. The [[enquiry]] showed training must [[ensure]] safety and [[enforce]] rules. What would [[ensue]] could [[enrich]] every family.",
      "They chose to [[engage]], [[enlarge]] pipes, and [[enhance]] performance. New skills would [[energize]] work and [[enlighten]] them. Their [[enlightenment]] came from patient questions."
    ],
