      "那位赞助者想象自己能控制整个企业，认为任何实体的环境责任都不重要。他恳求梅放行，却不肯承认自己的羡慕。",
      "梅要求检查入口与环境安排。节目只是一个小插曲，疾病流行更需要关注；大家的热情转向帮助村民，而演出等到安全时才开始。"
