      "巡使不接受只看衣装与女性气质的议论，她查看铁质栅栏、饲料与水中的纤维，发现虚弱的禽鸟患了热病。",
      "她让同伴取水检测，砍倒挡路枯树。村民的反馈证明污染来自收费站，同行友谊比一场摆宴更有用。"
