    "id": "expansion-b-004",
    "title": "灯塔侧翼的火焰",
    "englishTitle": "Flames at the Lighthouse",
    "category": "悬疑案",
    "tag": "雾城异闻",
    "color": "#e5dce9",
    "symbol": "⌕",
    "mood": "疑虑 → 发现 → 释然",
    "cn": [
      "守塔人因身体不适错过巡检。塔楼的灯具接头需要修理，旗边与法兰绒窗帘一起拍打墙壁。",
      "一片漆屑、一只烧瓶和灯塔侧翼的火焰揭示了破绽。有人把金属板压平，企图让光线闪过海面，引走船队。",
      "嫌疑人曾用甜言蜜语讨好厨师，夸赞每一种调味。林澈掀开金属板，制止逃跑的人，船队得以避开暗礁。"
    ],
    "en": [
      "The keeper’s poor [[fitness]] delayed repairs to a pipe [[fitting]]. He had to [[fix]] a loose light [[fixture]]. A [[flag]] began to [[flap]] beside a [[flannel]] curtain.",
      "A paint [[flake]] fell into a [[flask]]. On the tower’s [[flank]], a [[flame]] rose in a sudden [[flare]], followed by a blinding [[flash]]. Someone had used a [[flat]] plate and tried to [[flatten]] its edge to redirect the beam.",
      "The cook remembered a guest who would [[flatter]] her and praise every [[flavour]]. Lin found the plate’s [[flaw]]: it pointed ships toward the reef. As the guest tried to [[flee]], Lin covered the false light. The [[fleet]] turned safely toward the harbor."
    ],
