      "汽油泄露变成气态烟雾，仪表显示危险。林澈换好挡位，带人撤出，并召集邻居清理燃料。",
      "团伙头目凝视着星图，终于承认所谓天价宝藏是赝品。一群欢乐的人并未庆祝他的落网，而是庆祝伤者获救。"
