    "color": "#e5dce9",
    "symbol": "⌕",
    "mood": "疑虑 → 发现 → 释然",
    "cn": [
      "城内病患增加，诊所收入反而下降。调查员发现入口斜坡差一英寸，不完整改建计划使轮椅无法进入。",
      "越来越多的人抱怨，两套设备不兼容，费用却不断产生。负责人声称奇迹将至，未完成项目被无限期拖延。",
      "林澈把无障碍设施纳入新方案，所有人均可使用。诊所重获独立，一位印度医者带来检验结果，原先不可思议的账目终于解释清楚。"
    ],
    "en": [
      "The [[incidence]] of illness rose as clinic [[income]] fell. [[incidentally|Incidentally]], the ramp lacked one [[inch]]. Its [[incline]] and steep [[inclination]] came from an [[incomplete]], [[incorrect]] plan.",
      "Complaints became [[increasingly]] common. [[incompatible|Incompatible]] devices forced patients to [[incur]] charges that would [[increase]] again. The manager promised an [[incredible]] cure, then postponed repairs for an [[indefinite]] period, hoping to delay them [[indefinitely]].",
      "Lin made an [[inclusive]] plan [[include]] all patients and [[incorporate]] safe access. The clinic regained [[independence]] as an [[independent]] service. An [[indian|Indian]] doctor from [[india|India]] checked the bills. [[indeed|Indeed]], the missing ramp had exposed a wider fraud."
    ],
