    "id": "expansion-b-038",
    "title": "联结阵中的故意中断",
    "englishTitle": "The Deliberate Break in the Network",
    "category": "修仙志",
    "tag": "联阵学堂",
    "color": "#dce5d9",
    "symbol": "☾",
    "mood": "疑虑 → 发现 → 释然",
    "cn": [
      "密集训练要求学徒互相配合。内务实习生在网络界面发现一次人为中断，破坏联结阵的相互作用。",
      "临时负责人说那只是间歇干扰。但中层教学室的内部线路被动过，国际来宾的交流也被切断。",
      "实习生在实习期间听到对话，发现对方故意阻挠交流。她说明意图与事实的区别，师生共同恢复正常联络。"
    ],
    "en": [
      "During [[intensive]] training, students would [[interact]] through linked wards. An [[intern]] studied their [[interaction]] on an [[interface]]: an [[intentional]] break prevented the wards from being able to [[interconnect]].",
      "The [[interim]] keeper blamed [[intermittent]] [[interference]], claiming no [[intent]] to [[interfere]]. But the [[interior]] of the [[intermediate]] teaching room held altered [[internal]] wires. Visitors from an [[international]] school lost their [[internet]] connection too.",
      "During her [[internship]], the student checked his [[intention]] against events. His [[interest]] was control: he had blocked academic [[intercourse]] and damaged [[interpersonal]] trust. Restoring the wires allowed the students to exchange ideas again."
    ],
