    "color": "#e5dce9",
    "symbol": "⌕",
    "mood": "疑虑 → 发现 → 释然",
    "cn": [
      "小岛灌溉账单金额忽高忽低。铁片生锈，离子检测却说明水未受污染；讽刺的是举报者自己把干净水卖给居民。",
      "林澈逐项核对意大利工人的记录，也听见岛上不同信仰居民的抱怨。争端与宗教无关，是供水商故意变更价格。",
      "他发布报告，无论居民身份都应公平供水。一件象牙装饰品上的私印连起账单，名为“杰克”的经理被找到。"
    ],
