      "A portrait of [[jesus|Jesus]] proved nothing. Lin compared [[jean]] labels, heard a metal [[jingle]], and watched a suspect [[jerk]] his [[jacket]]. A spilled drink’s [[jet]] revealed the false pocket; the man’s [[jaw]] tightened.",
      "The reporter wrote the [[journey]] in his [[journal]], protecting the [[jewish|Jewish]] owner from rumors. A [[joke]] restored the [[jolly]] room. The thief went to [[jail]], and the owner’s [[joyful]] smile expressed honest [[joy]]."
