      "法官与陪审团查看水罐上的木星图，并不能据此证明罪行。看守敏锐注意壶中果仁，知道自己关错了人。",
      "少年没有踢开门，而是递上键盘记录，说明只是搬运报废物。正义需要裁决理由，合理解释终于让他获释。"
