    "cn": [
      "最近城里出现激光幻象，说有潜伏妖兽。云岚查看纬度坐标和拉丁文笔记，发现木格栅后藏着车床。",
      "两个嫌疑人争执，后者把脏衣丢进洗衣房，笑声暴露其位置。仪器发射时，光影鞭打墙面，但园中没有野兽。",
      "律师提起诉讼，要求公布设备布局。公厕墙内薄层涂料形成假影，普通人也能理解，所谓魔法终于被拆穿。"
    ],
    "en": [
      "[[lately|Lately]], a [[laser]] projected a [[latent]] beast behind a [[lattice]]. Yun checked [[latitude]] marks and a [[latin|Latin]] note beside a [[lathe]]. Someone would [[launch]] the illusion again [[later]].",
      "Of two suspects, the [[latter]] fled toward the [[laundry]]. His [[laughter]] betrayed him. Beams seemed to [[lash]] the wall, but the [[lawn]] held no beast.",
      "A [[lawyer]] filed a [[lawsuit]] under city [[law]]. The [[layout]] revealed a reflective [[layer]] in the [[lavatory]] wall. Yun would [[lay]] the plans before every [[layman]], and the false haunting ended."
    ],
