    "color": "#e5dce9",
    "symbol": "⌕",
    "mood": "疑虑 → 发现 → 释然",
    "cn": [
      "旅船搁浅，游客受伤跛行。林澈发现石灰涂层的船板与石灰岩暗礁有关，船员划的直线并不可信。",
      "亚麻布内衬上有口红，联结着一名歌手。她嘴唇受伤仍作证，语言分析显示所谓线性记录被人改动。",
      "有限饮水旁混着烈酒，医生测了一升液体。大家在船边停留，听众终于明白歌手并非肇事者，而是救伤者的人。"
    ],
    "en": [
      "A [[liner]] struck [[limestone]] and injured a passenger’s [[limb]], leaving him with a [[limp]]. A coating of [[lime]] connected the damage to the reef. The captain’s [[linear]] chart drew a false [[line]].",
      "A [[linen]] curtain’s [[lining]] held [[lipstick]], creating a [[link]] to a singer. Her cut [[lip]] did not prevent testimony. A [[linguistic]] analysis showed that someone had altered the written course. A painted [[lion]] on the cabin marked the meeting place.",
      "Their water [[limit]] left only [[limited]] supplies. A [[liter]] of [[liquid]] contained [[liquor]], confirming sabotage. Passengers would [[linger]] beside the shore as a [[listener]] heard how the singer had carried the wounded to safety."
    ],
