    "id": "expansion-b-052",
    "title": "木屋里的机车日志",
    "englishTitle": "The Locomotive Log in the Lodge",
    "category": "悬疑案",
    "tag": "雾城档案",
    "color": "#e5dce9",
    "symbol": "⌕",
    "mood": "疑虑 → 发现 → 释然",
    "cn": [
      "孤独旅人住在山间木屋，渴望长寿，却收到高耸织机发出的预言。旅馆主人说只有买下木材才能消灾。",
      "林澈用经度记录比较机车日志，发现货运路线绕成环。松动门锁与垂下的线让织机在夜间发声。",
      "他放松绳索，看见纸条松松藏在木头里。蝗虫吃光附近粮田才是危机，合理物流恢复，村民不再依赖领主假话。"
    ],
    "en": [
      "A [[lonely]] traveler sought [[lodging]] in a [[lodge]], [[longing]] for [[longevity]]. A [[lofty]] [[loom]] whispered a warning. The [[lord]] claimed only buying his timber could stop disaster.",
      "Lin checked [[longitude]] against a [[locomotive]] [[log]]. The [[logistics]] route made a suspicious [[loop]]. A [[loose]] [[lock]] let hidden threads hang [[loosely]] from the loom.",
      "He would [[loosen]] them and test the claim’s [[logic]]. A [[logical]] inquiry exposed the false voice. A [[locust]] swarm, not fate, threatened the crops; restored deliveries brought real relief to the valley."
    ],
