    "mood": "疑虑 → 发现 → 释然",
    "cn": [
      "杂志称魔术师能靠磁力读心，女仆却发现机器维护记录。她提醒地方官，壮观效果不代表巨大力量。",
      "在大陆来的侍女帮忙下，林澈把主机与磁铁分开。所谓魔法主要靠磁性，穿制服的女主人被他礼貌询问。",
      "他放大故障痕迹，发现主要线路被人为改过。魔术师承认夸大磁力，女士们得到答谢，观众也不再被当成疯子。"
    ],
    "en": [
      "A [[magazine]] praised a [[magician]]’s [[magic]]. A [[maid]] found neglected [[machinery]] and asked the [[magistrate]] to inspect it. A [[magnificent]] effect did not prove great [[magnitude]].",
      "A [[maiden]] from the [[mainland]] helped separate a [[magnet]] from the [[mainframe]]. The trick relied [[mainly]] on [[magnetic]] pull and ordinary [[magnetism]]. Lin addressed the hostess as [[madam]] and checked the [[main]] circuit.",
      "He would [[magnify]] its damaged marks. The maker had failed to [[maintain]] the device, hiding poor [[maintenance]] behind spectacle. The audience was not [[mad]]; it had trusted a claim the magician now admitted was false."
    ],
