      "A [[merry]] merchant wanted to [[merge]] the guilds, but his accounts were a [[mess]]. Yun would not judge [[merit]] [[merely]] by rumor.",
      "She measured one [[metre]] on a [[metric]] ruler in the [[metropolitan]] workshop. A [[microcomputer]], [[microphone]], and [[microprocessor]] recorded the test. Under a [[microscope]], [[microscopic]] scratches showed that the stone was an alloy from a furnace, not a divine gift."
