    "id": "expansion-b-062",
    "title": "镜中的导弹",
    "englishTitle": "The Missile in the Mirror",
    "category": "悬疑案",
    "tag": "雾城档案",
    "color": "#e5dce9",
    "symbol": "⌕",
    "mood": "疑虑 → 发现 → 释然",
    "cn": [
      "失踪传教士的任务被说成奇迹，他的女主人却在雾中收到恐吓。一个守财奴借众人的不幸发财，使苦难加深。",
      "林澈发现镜中导弹是反射，恶作剧制造了误解。信件“先生”称呼被改动，毛线手套上有混合药液。",
      "搅拌器里的混合物证明真正来源。所谓“强大威力”只有幻象的力，林澈解释错误概念，悲惨的居民不再被误导。"
    ],
    "en": [
      "A [[missing]] [[missionary]] on a [[mission]] vanished in [[mist]]. His [[mistress]] received threats of a [[miracle]]. A [[miser]] profited from their [[misfortune]], deepening the town’s [[misery]] and making everyone [[miserable]].",
      "A [[mirror]] showed a [[missile]], but it was reflected [[mischief]]. A letter addressed to [[mister|Mister]] Lin had been altered to [[mislead]] people. A [[mitten]] carried chemicals from a [[mixer]] used to [[mix]] the image’s paint.",
      "The [[mixture]] exposed the source. Its [[mighty]] spectacle had no real [[might]]. Lin corrected the [[misconception]] before neighbors could [[misunderstand]] the grieving family. The threats ended when he found the hidden projector."
    ],
