    "id": "expansion-b-064",
    "title": "君主与沼地怪兽",
    "englishTitle": "The Monarch and the Moor Monster",
    "category": "修仙志",
    "tag": "沼地公案",
    "color": "#dce5d9",
    "symbol": "☾",
    "mood": "疑虑 → 发现 → 释然",
    "cn": [
      "君主每月征钱，说沼地怪兽必须接受贡品。修士看着纪念碑，知道所谓怪物只是饥饿猴群。",
      "月报监测到怪诞叫声，垄断商却把它当货币危机，逼居民抵押房屋。云岚向大家说明道德不能被恐怖故事绑架。",
      "她拖洗地面，发现猿猴留下足迹。穆斯林邻居与清真寺志愿者一起帮忙除蚊，凡人而非恶灵的合作让气氛好转。"
    ],
    "en": [
      "A [[monarch]] demanded a [[monthly]] tax against a [[monster]] on the [[moor]]. A [[monk]] beside the [[monument]] recognized hungry [[monkey|monkeys]], not a supernatural beast.",
      "A [[monitor]] captured [[monstrous]] cries. The [[monopoly]] seller called them a [[monetary]] crisis and demanded a [[mortgage]] from every family. Yun questioned the plan’s [[morality]] and [[moral]] purpose.",
      "She used a [[mop]] to expose tracks. [[moreover|Moreover]], [[mortal]] neighbors could cooperate: a [[moslem|Moslem]] resident and [[mosque]] volunteers removed [[mosquito]] pools nearby. The frightened village’s [[mood]] lifted when the fabricated danger was gone."
    ],
