      "In this [[multicultural]] village, [[multiple]] witnesses recorded each [[motion]] and [[movement]]. Duplicate tickets created a [[multitude]] only through [[multiplication]]: someone had chosen to [[multiply]] copies. The friend returned safely, and Lin explained the mistake."
