    "id": "expansion-b-066",
    "title": "博物馆的无声乐师",
    "englishTitle": "The Museum’s Silent Musician",
    "category": "修仙志",
    "tag": "无声琴案",
    "color": "#dce5d9",
    "symbol": "☾",
    "mood": "疑虑 → 发现 → 释然",
    "cn": [
      "博物馆的乐师被怀疑杀人，哑口的他只能用手势，邻居却窃窃私语。蘑菇汤与芥末羊肉留下谜团，互相指责让嫌疑变得神秘。",
      "强壮守卫活动肌肉，想逼供。云岚思量后让音乐家以旋律说明：害死人的不是神话毒物，是被换过的汤。",
      "乐师不能开口，却能在琴谱中记证。低声怨言终于消散，真正凶手被认出；众人理解了尊重与合作的价值。"
    ],
    "en": [
      "A [[musician]] at a [[museum]] faced a [[murder]] charge. The [[mute]] man communicated with gestures while neighbors would [[murmur]]; a [[mushroom]] soup beside [[mustard]] and [[mutton]] seemed a [[mysterious]] [[mystery]].",
      "A [[muscular]] guard flexed a [[muscle]], hoping to frighten a confession out of him. Yun chose to [[muse]] on the evidence. The man’s [[musical]] account showed that the soup had been replaced, not poisoned by a creature from [[myth]].",
      "A note in the score identified the [[murderer]]. Neighbors ceased to [[mutter]] accusations. Their [[mutual]] respect let the musician’s careful record speak when his voice could not."
    ],
