    "id": "expansion-b-067",
    "title": "教堂中殿的航海日志",
    "englishTitle": "The Navigation Log in the Nave",
    "category": "悬疑案",
    "tag": "雾城档案",
    "color": "#e5dce9",
    "symbol": "⌕",
    "mood": "疑虑 → 发现 → 释然",
    "cn": [
      "海军在教堂中殿查到航海日志。幼稚学徒只穿薄衣，打盹时被顽童恶作剧，钉子挂坏窄门。林澈指出真正伤害就是松钉造成的严重衣物破口。",
      "林澈递上餐巾，请本地水手讲述经过。国家与国籍不能决定可信度，叙述只需依照自然发生的事情。",
      "附近整洁住处的居民提供联合记录。水手舔掉勺上果酱，说证据多半来自平凡日常；林澈鼓励学徒认真观察，终于修好门。"
    ],
    "en": [
      "The [[navy]] found a [[navigation]] log in a church’s [[nave]]. A [[naive]] apprentice took a [[nap]] in the [[narrow]] doorway. A [[naughty]] prank left a [[nail]] exposed, tearing his coat until his arm was [[naked]]. Lin identified the real damage, [[namely]], a [[nasty]] tear caused by the loose nail.",
      "Lin offered a [[napkin]] and asked a [[native]] sailor for a [[narration]]. A [[national]] badge, a [[nation]], or [[nationality]] did not determine truth. A reliable [[narrative]] followed what happened [[naturally]] through ordinary human [[nature]].",
      "At a [[nearby]], [[neat]] lodging, [[naval]] officers joined a [[joint]] account. The sailor would [[lick]] jam from his spoon: evidence was [[mostly]] mundane. This [[natural]] insight could [[motivate]] the apprentice to observe carefully. They repaired the door together."
    ],
