    "cn": [
      "新建网络站旁鸟巢突然空了，十九名学生陷入噩梦般恐慌。报摊上的绰号纸条指向一个吵闹怪人，他只点头不答。修理工发现巢台被松动电线组成的网缠住。",
      "神经元模型与中子仪器其实未检测出任何危险。镍片与氮气记录均正常，所测伤害为零。",
      "林澈保持中立，仍提名无名修理工接受表彰。所谓高贵头衔只是名义，人们终于不再听信无稽之谈，鸟巢也恢复安静。"
    ],
    "en": [
      "A [[newly]] built [[network]] station stood beside an empty [[nest]]. [[nineteen|Nineteen]] students feared a [[nightmare]]. A [[newsstand]] note used a [[nickname]] for a [[noisy]] stranger, who answered only with a [[nod]]. The repairer found the nesting platform caught in a [[net]] of loose wires.",
      "A [[neuron]] model and a [[neutron]] instrument indicated [[nil]] danger. Tests of [[nickel]] plates and [[nitrogen]] were normal. Lin remained [[neutral]]; [[nevertheless]], he continued checking the missing birds.",
      "A [[noble]] title was only [[nominal]]. He chose to [[nominate]] the unknown repairer who restored the nesting platform. [[nonetheless|Nonetheless]], some repeated [[nonsense]] until the birds returned. Quiet evidence finally convinced the students."
    ],
