    "id": "expansion-b-074",
    "title": "歌剧院的不透明门",
    "englishTitle": "The Opaque Door at the Opera",
    "category": "悬疑案",
    "tag": "雾城档案",
    "color": "#e5dce9",
    "symbol": "⌕",
    "mood": "疑虑 → 发现 → 释然",
    "cn": [
      "歌剧院持续的行动缺少透明记录，操作员被说与对手合谋。林澈审问门对面的人，不想因个人意见压迫员工。",
      "厨房的洋葱掩盖鸦片气味。侍者把盘子端上台，想往前走，却被不透明门拦住。遗漏的入口照片解释了实际路线。",
      "光学检查解释了骗局，乐观的员工选择最佳安全方案。门重新可用后，他们反对无端指责并借机记录每次修理；自省要面对事实，不能只说一切没问题。"
    ],
    "en": [
      "An [[ongoing]] [[operation]] at an [[opera]] house lacked records. An [[operator]] could not [[operate]] the door, while an [[opponent]] waited [[opposite]] it. Lin refused to [[oppress]] workers based on [[opinion]].",
      "Kitchen [[onion]] masked [[opium]]. A waiter stepped [[onto]] the stage, hoping to move [[onward]] and [[onwards]], but the [[opaque]] door blocked him. The report had chosen to [[omit]] the only photograph of the [[opening]].",
      "Tests in [[optics]] explained the [[optical]] trick. [[optimism|Optimism]] returned as [[optimistic]] workers chose an [[optimal]] plan at the [[optimum]] light level. To examine [[oneself]] meant checking facts before saying everything was [[okay]]. Once the door was [[operational]], workers could [[oppose]] unfair blame and take the [[opportunity]] to document every repair."
    ],
