      "The owner would [[overestimate]] capacity and [[overload]] the circuit. [[overhead|Overhead]] wires showed an unsafe [[overlap]]. An [[overseas]] repairer worked [[overtime]] [[overnight]], finding broken parts beyond an [[overpass]].",
      "An [[overt]] report changed the [[overall]] ruling and helped [[overthrow]] the false claim. Inspectors could no longer [[overlook]] the fault. Neighbors ran to [[overtake]] and [[overturn]] a runaway cart safely before it could [[overwhelm]] anyone. The evidence was [[overwhelming]]."
