    "id": "expansion-b-078",
    "title": "猫头鹰与氧化的船桨",
    "englishTitle": "The Owl and the Oxidized Oar",
    "category": "悬疑案",
    "tag": "雾城档案",
    "color": "#e5dce9",
    "symbol": "⌕",
    "mood": "疑虑 → 发现 → 释然",
    "cn": [
      "船主欠下修船费，所有权一度被质疑。猫头鹰落在牛车上，药师看到桨边氧化物，知道不是神秘毒。",
      "晚上八点，货物包裹来到太平洋港口。不同包装写着同一协定，牡蛎和药袋得按正确步调卸下，氧气瓶不能挤压。",
      "臭氧警报是漏气导致。双方补上软垫，用水桶收集漏液，指出疼痛源于误触；船主承认欠款，工人得到补偿。"
    ],
    "en": [
      "An [[owl]] landed on an [[ox]] cart beside the boat. Its [[owner]] would [[owe]] repair money, and [[ownership]] was disputed [[owing]] to unpaid bills. An [[oxide]] showed that the oar could [[oxidize]], not curse its users.",
      "At eight [[p.m.]], a [[package]] reached the [[pacific|Pacific]] port. A [[packet]] carried the same [[pact]] as the main [[pack]]. Workers kept a steady [[pace]] while unloading an [[oyster]] crate beside an [[oxygen]] tank.",
      "An [[ozone]] alarm signaled leakage. A [[pad]] and a [[pail]] caught the spill. A worker’s [[pain]] came from a [[painful]] chemical touch. Compensation and a proper repair settled the account."
    ],
