    "id": "expansion-b-083",
    "title": "半岛上沉香的价格",
    "englishTitle": "The Price of Perfume on the Peninsula",
    "category": "修仙志",
    "tag": "半岛香案",
    "color": "#dce5d9",
    "symbol": "☾",
    "mood": "疑虑 → 发现 → 释然",
    "cn": [
      "半岛退休者把养老金花在香水表演上，广告说百分之百有效。云岚却从每便士账目看见价格比例失衡。",
      "企鹅模型栖在架上，摆锤的针穿透纸幕。老人察觉完美只是舞台效果，胡椒气味掩盖真正香水。",
      "云岚让演员继续表演，却公开每人的收益比例。或许表演能完美，账目仍需透明；透明规则减少欺骗造成的险境。"
    ],
    "en": [
      "On a [[peninsula]], an elder spent his [[pension]] on [[perfume]]. The advertisement promised one hundred [[percent]] success, but its [[percentage]] of real oil was low. Yun checked the price [[per]] [[penny]].",
      "A model [[penguin]] sat on a [[perch]] while a [[pendulum]] needle would [[penetrate]] a screen. This [[penetration]] was stagecraft, not [[perfection]]. [[pepper|Pepper]] hid the diluted scent. The elder began to [[perceive]] the trick.",
      "Yun let the actor [[perform]], but the [[performance]] required honest accounts. [[perhaps|Perhaps]] the show worked [[perfectly]]; its false medical promise still placed buyers in [[peril]]. Fair refunds ended that danger."
    ],
