    "id": "expansion-c-016",
    "title": "文艺复兴旅馆",
    "englishTitle": "The Renaissance Inn",
    "category": "悬疑案",
    "tag": "雾港档案",
    "color": "#dce5d9",
    "symbol": "☾",
    "mood": "疑虑 → 危机 → 明朗",
    "cn": [
      "偏远旅馆在翻修期间仍出租危险房间。客人要求清除碎玻璃、修好楼梯并续办消防许可。",
      "老板答应退款，却要求客人推动议会废除安全规定。他重复承诺而没有悔意，擅演法庭戏的演员录下了回答。",
      "记者帮助替换假公告。演员成为住客代表，复印的旧许可又揭示官员曾压下投诉，旅馆终于停业修缮。"
    ],
    "en": [
      "A [[remote]] inn called “The [[renaissance]]” offered cheap [[rent]]. Its [[renovation]] would [[render]] three rooms unsafe, yet the owner refused their [[removal]] from the booking list. A guest asked him to [[remove]] broken glass, [[repair]] the stairs, and [[renew]] the fire permit.",
      "The owner promised to [[repay]] her fee if she would ask the council to [[repeal]] a safety rule. He began to [[repeat]] the promise [[repeatedly]], hoping [[repetition]] would conceal his [[repetitive]] lies. He could [[repel]] questions but did not [[repent]]. An actress whose [[repertoire]] included court dramas recorded his [[reply]].",
      "A [[reporter]] helped them [[replace]] the false notice with a truthful [[replacement]]. The owner’s [[representation]] of his inn had misled customers; the actress would [[represent]] them as their elected [[representative]]. No [[reproach]] stopped her. A hidden [[reproduction]] of the permit exposed official [[repression]] of past complaints, and the inn finally closed for repairs."
    ],
