    "id": "expansion-c-040",
    "title": "台阶上的不锈钢证词",
    "englishTitle": "The Stainless-Steel Evidence",
    "category": "悬疑案",
    "tag": "雾港档案",
    "color": "#dce5d9",
    "symbol": "☾",
    "mood": "疑虑 → 危机 → 明朗",
    "cn": [
      "职员在剧场突然踉跄，胸牌沾着茶渍。楼梯口被木桩堵住，他无法离开。",
      "厨房只有陈面包，厨子说话结巴。法官耐心让他陈述，不用惊吓逼供。",
      "记录揭示政客挪用食物，工人正面临饥饿。法官用固定摄像资料核对单据，找出失踪配送，并建立一致检查标准。"
    ],
    "en": [
      "A [[staff]] member crossed the [[stage]] and began to [[stagger]]. A tea [[stain]] spread across his [[stainless]] badge. He tried to reach the [[stair]], but the [[staircase]] ended at a blocked [[stairway]]. Someone had driven a [[stake]] into the landing.",
      "The kitchen’s [[staple]] bread was [[stale]], and a severed herb [[stalk]] lay by the [[stall]]. The cook would [[stammer]] when asked to [[state]] what happened. A judge did not [[startle]] him; she let him give a [[statement]] from his own [[standpoint]].",
      "The inquiry found that workers faced [[starvation]], while a [[statesman]] had diverted food. They would [[starve]] if a rigid [[standard]] stayed unchanged. The judge proposed to [[standardize]] inspections, checking a [[static]] display against a [[stationary]] camera. A receipt among the [[stationery]] exposed the missing deliveries. The official resigned, and the kitchens reopened."
    ],
