    "id": "expansion-c-050",
    "title": "合成药片的尾巴标签",
    "englishTitle": "The Tail Label on the Synthetic Tablets",
    "category": "悬疑案",
    "tag": "雾港档案",
    "color": "#dce5d9",
    "symbol": "☾",
    "mood": "疑虑 → 危机 → 明朗",
    "cn": [
      "药剂师建立系统记录，助手答应把合成药片各批结果列成表。一个画着尾巴的样本标签却消失了。",
      "她在裁缝柜台后发现被小钉固定的标签，谨慎询问，听说一名少年善于驯兽。",
      "少年发现动物毛色因药物暴露变成黄褐色，水箱也有漏油车的污染。助手藏标签意图隐瞒，药剂师召回受影响药片。"
    ],
    "en": [
      "A [[systematic]] chemist built a [[system]] for drug [[synthesis]]. To [[synthesize]] a safe [[synthetic]] [[tablet]], she recorded every batch [[systematically]]. Her assistant called the method [[systematical]] and promised to [[tabulate]] every result.",
      "A missing [[tag]] from a sample showed a creature’s [[tail]]. The assistant had used a [[tack]] to fasten it behind a [[tailor]]’s counter. The chemist chose [[tact]] over accusation, using patient [[tactics]] to [[tackle]] the theft. The tailor told a [[tale]] about a boy with remarkable [[talent]] for training animals.",
      "The boy could [[tame]] the animal, but its fur had turned [[tan]] after chemical exposure. He found a wire [[tangle]] in the water [[tank]]. A parked [[tanker]] was leaking into its feed. The assistant had removed the tag to hide contamination, and the chemist recalled every affected tablet."
    ],
