    "title": "电报局的焦油脚印",
    "englishTitle": "Tar Footprints at the Telegraph Office",
    "category": "悬疑案",
    "tag": "雾港档案",
    "color": "#dce5d9",
    "symbol": "☾",
    "mood": "疑虑 → 危机 → 明朗",
    "cn": [
      "在电报局跑腿的少年发现漏水龙头下的焦油脚印，封管胶带渐窄，旁边电报提到走私目标。",
      "技师解释旧通信设备遭破坏。走私者篡改关税通知，把货物伪装成教学用品以逃税。",
      "志愿队循脚印找到望远镜商店。店员撕毁电报并嘲弄少年，但他记得违禁物的苦味，帮助警方找到货物。"
    ],
    "en": [
      "A [[teenager]] doing a [[task]] at the [[telecommunications]] office found [[tar]] beneath a leaking [[tap]]. The [[tape]] around the pipe would [[taper]] near a broken valve. A [[telegram]] described a hidden [[target]] of the smugglers’ plan.",
      "A [[technician]] gave a [[technical]] explanation of the [[telegraph]] damage. New [[technology]] required a different [[technique]], and repairing the old [[telex]] was [[tedious]]. The smugglers had altered a [[tariff]] notice to evade a cargo [[tax]], disguising their shipment as school [[teaching]] materials.",
      "A volunteer [[team]] followed the footprints to a [[telescope]] shop. The clerk tried to [[tease]] the boy, then [[tear]] the message. But the boy remembered the contraband’s bitter [[taste]]. Officers found it behind telescope crates. The boy’s steady [[temperament]] overcame his fear, and the telegram was restored."
    ],
